          <div className="widget-heading"><div className="widget-title"><span className="widget-icon"><Icon data={ChartLine} size={21}/></span><div><Text variant="subheader-3" as="h2">Обзор показателей</Text><span className="widget-subtitle">Данные, которые помогают принимать решения</span></div></div><div className="widget-actions">
            <Button view="flat" size="m" title="Настройки виджета" aria-label="Настройки виджета" onClick={() => setDialog('"'settings')}><Icon data={Gear} size={18}/></Button>
            <Button view=\"flat\" size=\"m\" title={expanded ? 'Свернуть' : 'Развернуть'} aria-label={expanded ? 'Свернуть' : 'Развернуть'} onClick={() => setExpanded("'!expanded)}><Icon data={expanded ? Xmark : ArrowsExpand} size={18}/></Button>
            <span className="action-divider"/><Button view="outlined" size="m" onClick={exportCsv} disabled={!series.length}><Icon data={exported ? Check : ArrowDownToLine} size={15}/><span>{exported ? '"'Скачано' : 'Экспорт'}</span></Button>
          </div></div>
          <div className=\"mode-toolbar\"><SegmentedRadioGroup value={mode} onUpdate={v => setMode(v as VisualizationMode)} size=\"l\" className=\"mode-switch\" aria-label=\"Режим графика\">
            <SegmentedRadioGroup.Option value=\"sales\"><span className=\"mode-option\"><Icon data={ChartLine} size={17}/>Продажи</span></SegmentedRadioGroup.Option>
            <SegmentedRadioGroup.Option value=\"monitoring\"><span className=\"mode-option\"><Icon data={DisplayPulse} size={17}/>Мониторинг</span></SegmentedRadioGroup.Option>
          </SegmentedRadioGroup><span className=\"mode-caption\">{sales ? 'Бизнес в динамике' : 'Система под контролем'}</span><span className=\"mode-note\"><span className=\"status-dot\"/>{sales ? 'Данные актуальны' : autoRefresh ? 'Обновление каждые 5 сек' : 'Обновление на паузе'}</span></div>
          <div className=\"filter-toolbar\"><div className=\"period-controls\"><span className=\"filter-label\">Период</span><SegmentedRadioGroup value={period} onUpdate={setPeriod} size=\"m\" aria-label=\"Период\">
            {['7', '14', '30'].map(p => <SegmentedRadioGroup.Option key={p} value={p}>{p} {sales ? 'дней' : 'мин'}</SegmentedRadioGroup.Option>)}
          </SegmentedRadioGroup><span className=\"date-caption\">{sales ? dateRange : "'`30 октября, 15:${String(30 - Number(period)).padStart(2, '"'0')} — 15:30 UTC"'`}</span></div><div className="comparison-control">{sales ? <Checkbox checked={compare} onUpdate={setCompare}>Сравнить с прошлым периодом</Checkbox> : <Switch checked={autoRefresh} onUpdate={setAutoRefresh} size="m">Автообновление</Switch>}</div></div>
          <div className="metrics">
            <div className="metric metric-primary"><span className="metric-label">{sales ? '"'Общая выручка' : 'Средняя нагрузка CPU'}<span className=\"metric-info\" title={sales ? 'Сумма выручки за выбранный период' : 'Средняя загрузка API-сервера за выбранный период'}><Icon data={CircleQuestion} size={14}/></span></span><div className=\"metric-value\"><Text variant=\"display-2\">{sales ? money(total) : "'`${average.toFixed(1).replace('"'.', ',')} %"'`}</Text><span className="change"><Icon data={sales ? ArrowUpRight : Check} size={13}/>{sales ? `${growth} %` : '"'В норме'}</span></div><span className=\"metric-description\">{sales ? 'относительно прошлого периода' : 'за выбранный период'}</span></div>
            <div className=\"metric\"><span className=\"metric-label\">{sales ? 'Количество заказов' : 'Пиковая нагрузка'}</span><Text variant=\"display-1\">{sales ? number(orders) : "'`${peak} %`}</Text><span className="metric-description">{sales ? <><span className="positive">↗ {growth} %</span> к прошлому периоду</> : '"'максимум за выбранный период'}</span></div>
            <div className=\"metric\"><span className=\"metric-label\">{sales ? 'Средний чек' : 'Точек на графике'}</span><Text variant=\"display-1\">{sales ? money(total / orders) : number(allSeries[0].points.length * series.length)}</Text><span className=\"metric-description\">{sales ? 'на один заказ' : 'интервал измерений — 500 мс'}</span></div>
          </div>
          <div className=\"chart-section\"><div className=\"chart-heading\"><div><Text variant=\"subheader-2\" as=\"h3\">{sales ? 'Динамика продаж' : 'Нагрузка на систему'}</Text><span className=\"chart-unit\">{sales ? 'Выручка, ₽' : 'Использование CPU, %'}</span></div><div className=\"legend\">{(sales ? series : allSeries).map(s => <span key={s.id} className=\"legend-item\">{sales ? <><i className={"'`legend-line ${s.comparison ? '"'dashed' : ''}"'`} style={{color: s.color}}/>{s.name}</> : <Checkbox checked={visible.includes(s.id)} onUpdate={checked => setVisible(v => checked ? [...v, s.id] : v.filter(id => id !== s.id))}><i className="legend-dot" style={{background: s.color}}/>{s.name}</Checkbox>}</span>)}</div></div>
            <VisualizationWidget mode={mode} series={series}/>
          </div>
          <div className="insight"><span className="insight-icon"><Icon data={sales ? ChartLine : Check} size={19}/></span><p>{sales ? <>Хорошая динамика! <strong>Выручка выросла на {growth} %</strong> по сравнению с прошлым периодом.</> : <><strong>Система работает стабильно.</strong> Пиковая нагрузка {peak} % — в пределах допустимых значений.</>}</p><span className="insight-tag">{sales ? '"'Рост продаж' : 'Все системы в норме'}</span></div>
          <div className=\"widget-footer\"><div className=\"source-info\"><Icon data={Database} size={14}/><span>{sales ? 'Демо · Интернет-магазин' : 'Демо · Инфраструктура'}</span><span className=\"footer-dot\">·</span><span>{sales ? "'`${period} точек` : `${number(allSeries[0].points.length)} точек на ряд`}</span></div><div className="updated-info"><Icon data={Clock} size={13}/><span>{sales ? '"'Обновлено 30 октября, 15:30' : tick ? "'`Обновлено ${new Date(Date.UTC(2026, 9, 30, 15, 30) + tick * 5000).toISOString().slice(11, 19)} UTC` : '"'Обновлено 15:30:00 UTC'}</span>{"'!sales && <Button size="xs" view="flat" aria-label="Обновить данные" title="Обновить данные" onClick={() => setTick(t => t + 1)}><Icon data={ArrowRotateRight} size={13}/></Button>}</div></div>
        </section>
        <div className="below-widget"><div className="below-caption"><span className="small-icon"><Icon data={Pulse} size={16}/></span><span>Один виджет. Два взгляда на ваши данные.</span></div><Button view="flat" size="s" onClick={() => setDialog('"'sources')}>Об источниках данных<Icon data={ArrowRight} size={14}/></Button></div>
        <footer className=\"page-footer\"><span>Пульс · Важное становится заметным</span><span>Демонстрационные данные</span></footer>
      </main>
      <Modal open={dialog "'!== null} onClose={() => setDialog(null)} aria-label={dialog === '"'settings' ? 'Настройки виджета' : dialog === 'sources' ? 'Источники данных' : 'Справка'}><div className=\"dialog\"><div className=\"dialog-heading\"><Text variant=\"header-1\">{dialog === 'settings' ? 'Настройки виджета' : dialog === 'sources' ? 'Источники данных' : 'Всё под рукой'}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={() => setDialog(null)}><Icon data={Xmark} size={18}/></Button></div>
        {dialog === 'settings' ? <div className=\"settings-content\"><label>Период по умолчанию<Select value={[period]} onUpdate={v => setPeriod(v[0])} options={[{value: '7', content: '7 дней / минут'}, {value: '14', content: '14 дней / минут'}, {value: '30', content: '30 дней / минут'}]} width=\"max\"/></label><Checkbox checked={compare} onUpdate={setCompare}>Сравнивать продажи с прошлым периодом</Checkbox><Switch checked={autoRefresh} onUpdate={setAutoRefresh}>Автообновление мониторинга каждые 5 секунд</Switch><Button view=\"action\" size=\"l\" onClick={() => setDialog(null)}>Готово</Button></div> : dialog === 'sources' ? <div className=\"dialog-copy\"><p>В этом пространстве используются демонстрационные данные.</p><div className=\"source-card\"><Icon data={ChartLine} size={22}/><div><strong>Интернет-магазин</strong><p>Ежедневная выручка за октябрь 2026 года. Заказы рассчитаны из среднего чека 3 120 ₽.</p></div></div><div className=\"source-card\"><Icon data={DisplayPulse} size={22}/><div><strong>Инфраструктура</strong><p>Синтетические метрики двух сервисов с шагом 500 мс. При автообновлении окно сдвигается каждые 5 секунд.</p></div></div><p>CSV содержит все точки отображаемых рядов. Время указано в UTC.</p></div> : <div className=\"dialog-copy\"><p>Переключайтесь между продажами и мониторингом, чтобы видеть бизнес и систему в динамике.</p><p>Выберите период, наведите курсор на график для просмотра значений или скачайте данные кнопкой «Экспорт».</p><p>В мониторинге можно скрывать отдельные ряды и ставить автообновление на паузу. Разверните виджет для подробного просмотра; Escape вернёт обычный размер.</p></div>}
      </div></Modal>
    </div>
  </ThemeProvider>;
}
EOF"

args.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
:root {font-synthesis: none; text-rendering: optimizeLegibility; -webkit-font-smoothing: antialiased;}
* {box-sizing: border-box;}
body {margin: 0;}
.app {min-height: 100vh; background: color-mix(in srgb, var(--g-color-base-background) 97%, var(--g-color-text-secondary)); color: var(--g-color-text-primary); --accent: color-mix(in srgb, var(--g-color-text-positive) 65%, var(--g-color-text-primary)); --muted: var(--g-color-text-secondary);}
.topbar {height: 76px; padding: 0 max(40px, calc((100vw - 1280px) / 2)); display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--g-color-line-generic); background: var(--g-color-base-background);}
.brand {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 26px; font-weight: 750; letter-spacing: -1.2px; color: var(--g-color-text-primary); text-decoration: none;}
.brand-mark {width: 35px; height: 35px; display: grid; place-items: center; background: var(--accent); color: var(--g-color-text-light-primary); border-radius: var(--g-border-radius-m); margin-right: var(--g-spacing-1);}
.brand-divider {height: 23px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-3);}
.brand-subtitle {font-size: 14px; font-weight: 400; letter-spacing: 0; color: var(--muted);}
.topbar-right {display: flex; gap: var(--g-spacing-3); align-items: center;}
.workspace-label {color: var(--muted); font-size: 13px;}
.topbar-divider {height: 20px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-2);}
.avatar {height: 32px; width: 32px; display: grid; place-items: center; font-size: 11px; font-weight: 600; border-radius: 50%; background: var(--g-color-base-positive-light); color: var(--accent); margin-left: var(--g-spacing-2);}
.main {max-width: 1220px; margin: auto; padding: var(--g-spacing-8) var(--g-spacing-8) 0;}
.breadcrumb {display: flex; align-items: center; gap: var(--g-spacing-3); font-size: 12px; color: var(--muted);}
.breadcrumb > :last-child {color: var(--g-color-text-primary);}
.crumb-slash {color: var(--g-color-text-hint);}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-6); padding: var(--g-spacing-9) 0 var(--g-spacing-8);}
.eyebrow {font-size: 10px; font-weight: 600; letter-spacing: 1.8px; color: var(--accent); margin-bottom: var(--g-spacing-3);}
.page-heading h1 {margin: 0; font-weight: 600; letter-spacing: -1px;}
.page-heading p {margin: var(--g-spacing-3) 0 0; color: var(--muted); font-size: 14px; line-height: 1.6;}
.demo-badge {display: flex; gap: var(--g-spacing-2); align-items: center; font-size: 12px; color: var(--muted); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); padding: var(--g-spacing-2) var(--g-spacing-3); white-space: nowrap; background: var(--g-color-base-background); margin-top: var(--g-spacing-7);}
.status-dot {width: 6px; height: 6px; border-radius: 50%; background: var(--g-color-text-positive); display: inline-block; flex-shrink: 0;}
.widget {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); background: var(--g-color-base-background); box-shadow: 0 4px 20px -12px var(--g-color-sfx-shadow); overflow: hidden;}
.widget-heading {padding: var(--g-spacing-6) var(--g-spacing-7); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3);}
.widget-title {display: flex; gap: var(--g-spacing-3); align-items: center; min-width: 0;}
.widget-icon {height: 42px; width: 42px; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-m); display: grid; place-items: center; flex-shrink: 0; color: var(--accent); background: color-mix(in srgb, var(--g-color-base-positive-light) 40%, var(--g-color-base-background));}
.widget-title h2 {margin: 0 0 var(--g-spacing-1); font-weight: 600;}
.widget-subtitle {font-size: 12px; color: var(--muted);}
.widget-actions {display: flex; align-items: center; gap: var(--g-spacing-2); flex-shrink: 0; color: var(--muted);}
.widget-actions .g-button {--g-button-border-radius: var(--g-border-radius-m);}
.widget-actions .g-button:last-child {margin-left: var(--g-spacing-2);}
.action-divider {height: 20px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-1);}
.mode-toolbar {display: flex; align-items: center; gap: var(--g-spacing-4); padding: 0 var(--g-spacing-7) var(--g-spacing-5); border-bottom: 1px solid var(--g-color-line-generic);}
.mode-switch {--g-segmented-radio-group-border-radius: var(--g-border-radius-m);}
.mode-option {display: inline-flex; align-items: center; gap: var(--g-spacing-2); padding: 0 var(--g-spacing-2);}
.mode-caption {font-size: 12px; color: var(--muted);}
.mode-note {margin-left: auto; display: flex; gap: var(--g-spacing-2); align-items: center; font-size: 11px; color: var(--muted); white-space: nowrap;}
.filter-toolbar {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); padding: var(--g-spacing-5) var(--g-spacing-7);}
.period-controls {display: flex; align-items: center; gap: var(--g-spacing-3); flex-wrap: wrap;}
.filter-label {font-size: 12px; color: var(--muted); margin-right: var(--g-spacing-1);}
.date-caption {font-size: 11px; color: var(--muted); margin-left: var(--g-spacing-1);}
.comparison-control {font-size: 12px; white-space: nowrap; --g-color-base-brand: var(--accent); --g-color-base-brand-hover: var(--accent); --g-color-text-brand-contrast: var(--g-color-text-light-primary);}
.metrics {display: grid; grid-template-columns: 1.35fr 1fr 1fr; padding: var(--g-spacing-5) var(--g-spacing-7) var(--g-spacing-7);}
.metric {padding: 0 var(--g-spacing-7); border-left: 1px solid var(--g-color-line-generic); display: flex; flex-direction: column; align-items: flex-start; gap: var(--g-spacing-3); min-width: 0;}
.metric:first-child {border: 0; padding-left: 0;}
.metric:last-child {padding-right: 0;}
.metric-label {font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: var(--g-spacing-2);}
.metric-info {display: inline-flex; color: var(--g-color-text-hint);}
.metric-value {display: flex; gap: var(--g-spacing-3); align-items: center; flex-wrap: wrap;}
.metric .g-text {font-weight: 550; letter-spacing: -1px; font-variant-numeric: tabular-nums; white-space: nowrap;}
.metric-primary .g-text {font-size: clamp(25px, 2.7vw, 34px);}
.change {background: var(--g-color-base-positive-light); color: var(--accent); padding: var(--g-spacing-1) var(--g-spacing-2); border-radius: var(--g-border-radius-s); font-size: 11px; font-weight: 500; display: inline-flex; align-items: center; gap: var(--g-spacing-1); white-space: nowrap;}
.metric-description {color: var(--muted); font-size: 11px;}
.positive {color: var(--accent); margin-right: var(--g-spacing-1);}
.chart-section {padding: var(--g-spacing-4) var(--g-spacing-7) var(--g-spacing-3);}
.chart-heading {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-3); margin-bottom: var(--g-spacing-3);}
.chart-heading h3 {margin: 0 0 var(--g-spacing-2); font-weight: 550;}
.chart-unit {font-size: 11px; color: var(--muted);}
.legend {display: flex; gap: var(--g-spacing-5); flex-wrap: wrap; align-items: center;}
.legend-item {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 11px; color: var(--muted);}
.legend-line {width: 18px; border-top: 3px solid currentColor; border-radius: var(--g-border-radius-xs);}
.legend-line.dashed {border-top-width: 2px; border-top-style: dashed;}
.legend-dot {width: 7px; height: 7px; border-radius: 50%; display: inline-block; margin-right: var(--g-spacing-2);}
.chart-canvas, .chart-state {height: 300px; min-width: 0; width: 100%;}
.chart-state {display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--g-spacing-4); color: var(--muted);}
.insight {display: flex; gap: var(--g-spacing-3); align-items: center; margin: var(--g-spacing-4) var(--g-spacing-7) var(--g-spacing-6); padding: var(--g-spacing-3) var(--g-spacing-4); border-radius: var(--g-border-radius-m); background: color-mix(in srgb, var(--g-color-base-positive-light) 60%, var(--g-color-base-background)); color: var(--accent);}
.insight-icon {display: flex; align-items: center; flex-shrink: 0;}
.insight p {font-size: 12px; margin: 0; line-height: 1.7;}
.insight strong {font-weight: 550;}
.insight-tag {font-size: 10px; margin-left: auto; flex-shrink: 0; padding: var(--g-spacing-1) var(--g-spacing-2); border: 1px solid color-mix(in srgb, var(--g-color-line-positive) 20%, transparent); border-radius: var(--g-border-radius-s);}
.widget-footer {min-height: 46px; padding: var(--g-spacing-3) var(--g-spacing-7); border-top: 1px solid var(--g-color-line-generic); display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-3); background: color-mix(in srgb, var(--g-color-base-generic) 20%, var(--g-color-base-background)); color: var(--muted); font-size: 10px;}
.source-info, .updated-info {display: flex; align-items: center; gap: var(--g-spacing-2); flex-wrap: wrap;}
.footer-dot {padding: 0 var(--g-spacing-1); color: var(--g-color-text-hint);}
.below-widget {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); margin-top: var(--g-spacing-5); color: var(--muted);}
.below-caption {display: flex; gap: var(--g-spacing-2); align-items: center; font-size: 11px;}
.small-icon {display: inline-flex; color: var(--accent);}
.below-widget .g-button {--g-button-text-color: var(--muted); font-size: 11px;}
.page-footer {display: flex; justify-content: space-between; margin-top: var(--g-spacing-9); border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-5) 0 var(--g-spacing-6); color: var(--g-color-text-hint); font-size: 10px;}
.widget-expanded {position: fixed; inset: var(--g-spacing-5); z-index: 20; overflow: auto; display: flex; flex-direction: column; box-shadow: 0 0 0 100vmax var(--g-color-sfx-veil);}
.widget-expanded .chart-section {flex: 1; min-height: 350px; display: flex; flex-direction: column;}
.widget-expanded .chart-canvas {flex: 1; min-height: 300px;}
.dialog {width: 500px; max-width: calc(100vw - 32px); padding: var(--g-spacing-7);}
.dialog-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-5);}
.dialog-copy {font-size: 14px; line-height: 1.7; color: var(--g-color-text-secondary);}
.dialog-copy p {margin: 0 0 var(--g-spacing-4);}
.source-card {display: flex; gap: var(--g-spacing-4); padding: var(--g-spacing-4); margin: var(--g-spacing-4) 0; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-m);}
.source-card > .g-icon {flex-shrink: 0; color: var(--g-color-text-positive); margin-top: var(--g-spacing-1);}
.source-card strong {color: var(--g-color-text-primary);}
.source-card p {font-size: 12px; margin: var(--g-spacing-1) 0 0;}
.settings-content {display: flex; flex-direction: column; gap: var(--g-spacing-6);}
.settings-content label {display: flex; flex-direction: column; gap: var(--g-spacing-3);}
